import{_ as e,o as r,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Month 2021: Qemu: librbd vs krbd performance","description":"","frontmatter":{"title":"Ceph Month 2021: Qemu: librbd vs krbd performance","date":"2021-06-21T00:00:00.000Z","updated":"2021-06-22T00:00:00.000Z","tags":["[Ceph]","[librbd]","[krbd]","[性能比较]","[客户端]"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_Qemu_-_librbd_vs_krbd_performance.md","filePath":"posts/2021/Ceph_Month_2021_-_Qemu_-_librbd_vs_krbd_performance.md","lastUpdated":1780459816000}'),t={name:"posts/2021/Ceph_Month_2021_-_Qemu_-_librbd_vs_krbd_performance.md"};function o(d,a,b,_,n,s){return r(),l("div",null,[...a[0]||(a[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><p>本次会议主要讨论和比较了Ceph存储系统中librbd和krbd两种客户端在不同场景下的性能表现。</p><h4 id="会议目的" tabindex="-1">会议目的： <a class="header-anchor" href="#会议目的" aria-label="Permalink to &quot;会议目的：&quot;">​</a></h4><p>为了解答客户关于librbd和krbd性能差异的疑问，特别是针对特定工作负载（Kimu workloads），会议旨在通过数据收集和比较，展示这两种客户端的性能特点。</p><h4 id="主要讨论内容" tabindex="-1">主要讨论内容： <a class="header-anchor" href="#主要讨论内容" aria-label="Permalink to &quot;主要讨论内容：&quot;">​</a></h4><ol><li><p><strong>测试目标和方法</strong>：</p><ul><li>定义了四个主要测试场景，包括在虚拟机中使用librbd和krbd，以及在物理主机上使用librbd和krbd的测试。</li><li>测试采用随机读写，块大小为4k、64k和4MB，使用不同的I/O引擎。</li><li>每个场景进行了五次非连续运行，以确保结果的可比性。</li></ul></li><li><p><strong>测试结果</strong>：</p><ul><li>在虚拟机环境中，librbd和krbd的性能几乎相同，平均性能差异在100%左右。</li><li>在物理主机上，krbd的性能显著优于librbd，特别是在高队列深度（q depth）和大块大小的情况下。</li><li>发现librbd在特定设置下有一个约20,000 IOPS的性能上限。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>计划使用Pacific版本进行进一步测试，并重新比较结果。</li><li>将公开fio配置，以便其他人可以在自己的系统上进行测试。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认了librbd在特定环境下的性能上限约为20,000 IOPS。</li><li>计划进行进一步的测试以验证和探索性能差异的原因。</li></ul><h4 id="后续行动" tabindex="-1">后续行动： <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动：&quot;">​</a></h4><ul><li>使用Pacific版本进行测试，并重新评估性能数据。</li><li>公开fio配置，促进社区的进一步测试和验证。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>会议通过定义测试场景和方法，收集并分析了librbd和krbd的性能数据，为解答客户疑问提供了科学依据。后续将继续进行深入测试和分析，以更好地理解性能差异的原因，并探索可能的优化方案。</p>',13)])])}const c=e(t,[["render",o]]);export{p as __pageData,c as default};
